def capitalize_first_last_letters(s):
    words = s.split()
    result = []
    for word in words:
        if len(word) == 1:
            result.append(word.upper())
        else:
            result.append(word[0].upper() + word[1:-1] + word[-1].upper())
    return ' '.join(result)
```

