def remove_words(string_list, chars_or_strings):
    result = []
    for item in string_list:
        cleaned_item = item
        for char_or_string in chars_or_strings:
            if char_or_string in cleaned_item:
                cleaned_item = cleaned_item.replace(char_or_string, '')
        result.append(cleaned_item)
    return result
```

